import{_ as r,C as i,o as t,c as s,aj as a,E as l}from"./chunks/framework.D04Qc2jV.js";const m=JSON.parse('{"title":"Arbeiten mit mehreren Agenten","description":"","frontmatter":{"title":"Arbeiten mit mehreren Agenten"},"headers":[],"relativePath":"kapitel/10-mehrere-agenten.md","filePath":"kapitel/10-mehrere-agenten.md"}'),u={name:"kapitel/10-mehrere-agenten.md"};function d(g,e,h,o,c,b){const n=i("FeedbackForm");return t(),s("div",null,[e[0]||(e[0]=a('<h1 id="kapitel-10-arbeiten-mit-mehreren-agenten" tabindex="-1">Kapitel 10: Arbeiten mit mehreren Agenten <a class="header-anchor" href="#kapitel-10-arbeiten-mit-mehreren-agenten" aria-label="Permalink to &quot;Kapitel 10: Arbeiten mit mehreren Agenten&quot;">​</a></h1><h2 id="rechercheur-umsetzer-und-kontrolleur" tabindex="-1">Rechercheur, Umsetzer und Kontrolleur <a class="header-anchor" href="#rechercheur-umsetzer-und-kontrolleur" aria-label="Permalink to &quot;Rechercheur, Umsetzer und Kontrolleur&quot;">​</a></h2><p>Stellen Sie sich vor, Sie wollen eine gründliche Marktanalyse erstellen. Ein einzelner Agent könnte das versuchen: recherchieren, auswerten, schreiben, prüfen, alles in einem Durchgang. Das funktioniert. Aber es hat eine Schwäche. Derselbe Agent, der recherchiert hat, ist auch derjenige, der bewertet, ob seine eigene Recherche gut war. Das ist wie ein Autor, der sein eigenes Manuskript lektoriert: Er sieht Fehler, die er selbst gemacht hat, schlechter als eine zweite Person.</p><p>Multi-Agenten-Systeme lösen dieses Problem, indem verschiedene Agenten verschiedene Rollen übernehmen. Einer recherchiert. Ein anderer schreibt. Ein dritter prüft das Ergebnis kritisch. Dieses Zusammenspiel erzeugt oft bessere Ergebnisse als ein einzelner Agent, der alles alleine macht.</p><p>Aber Multi-Agenten-Systeme bringen auch neue Komplexität. Dieses Kapitel zeigt Ihnen die fünf wichtigsten Muster für die Zusammenarbeit mehrerer Agenten, erklärt, wann jedes Muster sinnvoll ist, und gibt Ihnen konkrete Beispiele für den Alltag von Selbständigen.</p><h2 id="warum-mehrere-agenten-besser-sein-konnen-als-einer" tabindex="-1">Warum mehrere Agenten besser sein können als einer <a class="header-anchor" href="#warum-mehrere-agenten-besser-sein-konnen-als-einer" aria-label="Permalink to &quot;Warum mehrere Agenten besser sein können als einer&quot;">​</a></h2><p>Bevor wir in die Muster einsteigen, lohnt sich die Frage: Wann braucht es überhaupt mehrere Agenten?</p><p>Anthropic hat in seinem viel zitierten Artikel über das Bauen wirksamer Agenten eine klare Empfehlung gegeben, die in diesem Buch bereits mehrfach angeklungen ist: Beginnen Sie immer mit der einfachsten Lösung. Mehr Komplexität nur hinzufügen, wenn sie nachweisbar bessere Ergebnisse bringt.</p><p>Das gilt auch hier. Für einfache Aufgaben ist ein einzelner, gut konfigurierter Agent besser als ein kompliziertes Multi-Agenten-System. Mehrere Agenten lohnen sich dann, wenn eine Aufgabe so groß oder vielschichtig ist, dass ein einzelner Agent dabei an seine Kontextgrenzen stößt, wenn verschiedene Schritte verschiedene Qualitätskriterien haben, die voneinander unabhängig geprüft werden sollten, wenn Teile einer Aufgabe parallel bearbeitet werden könnten und dadurch Zeit gespart wird, oder wenn Qualitätssicherung durch einen unabhängigen Agenten nachweislich bessere Ergebnisse liefert als Selbstprüfung.</p><p>Für Selbständige trifft das selten auf tägliche Routineaufgaben zu, aber regelmäßig auf größere Projekte: eine umfangreiche Marktanalyse, ein Buchkapitel, ein komplexes Kundenangebot oder eine Website-Überarbeitung.</p><h2 id="muster-1-orchestrator-und-worker" tabindex="-1">Muster 1: Orchestrator und Worker <a class="header-anchor" href="#muster-1-orchestrator-und-worker" aria-label="Permalink to &quot;Muster 1: Orchestrator und Worker&quot;">​</a></h2><p>Das Orchestrator-Worker-Muster ist das grundlegendste Multi-Agenten-Muster. Ein zentraler Agent, der Orchestrator, übernimmt die Planung. Er empfängt die Gesamtaufgabe, zerlegt sie in Teilaufgaben und delegiert diese an spezialisierte Worker-Agenten. Die Worker führen ihre Aufgaben aus und liefern Ergebnisse zurück. Der Orchestrator sammelt die Ergebnisse und fügt sie zusammen.</p><p>Was den Orchestrator von einem einfachen Prompt unterscheidet, ist seine Fähigkeit, dynamisch zu entscheiden, welche Teilaufgaben notwendig sind und in welcher Reihenfolge sie bearbeitet werden, weil er sich auf die Ergebnisse der vorherigen Schritte stützt.</p><p>Ein praktisches Beispiel für Selbständige: Sie wollen ein zwölfseitiges Briefingdokument für ein neues Kundenprojekt erstellen. Der Orchestrator empfängt diese Aufgabe und zerlegt sie in fünf Teilaufgaben: Marktumfeld recherchieren, Wettbewerbslandschaft analysieren, Zielgruppenprofile erstellen, Chancen und Risiken identifizieren, alles zu einem kohärenten Dokument zusammenfügen. Er delegiert die ersten vier Aufgaben an Worker-Agenten, wartet auf ihre Ergebnisse, prüft die Vollständigkeit und beauftragt dann den fünften Worker mit dem Zusammenführen.</p><p>Das Ergebnis ist ein Dokument, das strukturierter und vollständiger ist, als ein einzelner Agent in einem einzigen Durchgang produzieren könnte, weil jeder Worker in seinem Bereich tief geht, ohne den Gesamtkontext jonglieren zu müssen.</p><h2 id="muster-2-parallelisierung" tabindex="-1">Muster 2: Parallelisierung <a class="header-anchor" href="#muster-2-parallelisierung" aria-label="Permalink to &quot;Muster 2: Parallelisierung&quot;">​</a></h2><p>Das Parallelisierungs-Muster ist das effizienteste Multi-Agenten-Muster für Aufgaben, bei denen mehrere unabhängige Teilaufgaben gleichzeitig bearbeitet werden können.</p><p>Statt dass ein Agent zuerst Aufgabe A erledigt, dann B, dann C, werden A, B und C gleichzeitig von verschiedenen Agenten bearbeitet. Das spart Zeit, wenn die Teilaufgaben voneinander unabhängig sind und keine Aufgabe auf das Ergebnis einer anderen warten muss.</p><p>Ein praktisches Beispiel: Sie wollen die Websites von fünf Wettbewerbern analysieren. Statt dass ein Agent die fünf Websites nacheinander durchgeht, laufen fünf Agenten parallel, je einer pro Website. Das Ergebnis liegt in einem Fünftel der Zeit vor, und Sie haben am Ende fünf parallele Analysen, die ein zusammenführender Agent in eine Gesamtübersicht integriert.</p><p>Parallelisierung ist besonders nützlich bei Rechercheaufgaben mit mehreren Quellen, bei der gleichzeitigen Erstellung von Varianten, zum Beispiel fünf verschiedene Entwürfe für eine Einleitung, oder bei der Analyse großer Datenmengen, die in Segmente aufgeteilt werden können.</p><p>Eine praktische Einschränkung: Bei Codex Cloud laufen Aufgaben bereits in eigenen Umgebungen, was natürliche Parallelisierung unterstützt. Bei Claude Code und in lokalen Setups braucht Parallelisierung eine bewusstere Konfiguration. Für einfache Anwendungsfälle reicht es aber oft, mehrere Sitzungen parallel zu starten.</p><h2 id="muster-3-sequenzielles-verketten" tabindex="-1">Muster 3: Sequenzielles Verketten <a class="header-anchor" href="#muster-3-sequenzielles-verketten" aria-label="Permalink to &quot;Muster 3: Sequenzielles Verketten&quot;">​</a></h2><p>Das Sequenzierungs-Muster ist das einfachste, aber bei vielen Content-Aufgaben das wirkungsvollste. Eine Aufgabe wird in klar definierte, aufeinander aufbauende Schritte zerlegt. Das Ergebnis von Schritt 1 ist die Eingabe für Schritt 2, das Ergebnis von Schritt 2 ist die Eingabe für Schritt 3.</p><p>Dieser Ansatz eignet sich besonders gut, wenn jeder Schritt eine andere Qualitätsprüfung erfordert und wenn frühe Fehler nicht in spätere Schritte einfließen sollen.</p><p>Ein konkretes Beispiel für ein Blogkapitel: Schritt 1 ist die Recherche, Ergebnis ist ein strukturiertes Briefing. Schritt 2 ist die Gliederung auf Basis des Briefings. Schritt 3 ist der Erstentwurf auf Basis der geprüften Gliederung. Schritt 4 ist das Stilreview des Entwurfs. Schritt 5 ist die Faktenprüfung des überarbeiteten Entwurfs.</p><p>Bei jedem Schritt haben Sie als Mensch die Möglichkeit, das Ergebnis zu prüfen und zu korrigieren, bevor es in den nächsten Schritt einfließt. Das ist der entscheidende Unterschied zum Einsatz eines einzelnen Agenten für die gesamte Aufgabe: Fehler in frühen Schritten werden gestoppt, bevor sie sich durch das gesamte Dokument ziehen.</p><h2 id="muster-4-evaluator-und-optimierer" tabindex="-1">Muster 4: Evaluator und Optimierer <a class="header-anchor" href="#muster-4-evaluator-und-optimierer" aria-label="Permalink to &quot;Muster 4: Evaluator und Optimierer&quot;">​</a></h2><p>Das Evaluator-Optimizer-Muster ist das Muster für Qualitätssicherung. Ein Agent erzeugt ein Ergebnis. Ein zweiter Agent, der Evaluator, prüft dieses Ergebnis kritisch anhand klar definierter Kriterien und liefert konkretes Feedback. Der erste Agent überarbeitet das Ergebnis auf Basis des Feedbacks. Dieser Kreislauf wiederholt sich, bis das Ergebnis die Qualitätskriterien erfüllt.</p><p>Anthropic beschreibt dieses Muster als besonders wirksam, wenn es zwei Bedingungen gibt: erstens klare Bewertungskriterien, und zweitens die Fähigkeit des Agenten, aus Feedback messbar bessere Ergebnisse zu produzieren.</p><p>Für Selbständige eignet sich dieses Muster besonders für Texte mit hoher Außenwirkung. Sie könnten einen Evaluator-Agenten einrichten, der jedes Mal, wenn ein Textdraft vorliegt, nach folgendem Schema prüft: Ist die Kernthese klar? Sind alle Aussagen belegt? Stimmt der Ton für die Zielgruppe? Gibt es Unklarheiten, die ein Leser ohne Vorkenntnisse nicht verstehen würde? Welche drei Stellen müssen unbedingt überarbeitet werden?</p><p>Der Evaluator liefert kein neues Ergebnis, er liefert strukturiertes Feedback. Der schreibende Agent überarbeitet auf Basis dieses Feedbacks. Ein oder zwei Durchläufe reichen in der Praxis meistens aus. Das Ergebnis ist oft merklich besser als nach einem einzigen Durchgang ohne Prüfschritt.</p><h2 id="muster-5-routing" tabindex="-1">Muster 5: Routing <a class="header-anchor" href="#muster-5-routing" aria-label="Permalink to &quot;Muster 5: Routing&quot;">​</a></h2><p>Das Routing-Muster ist am nützlichsten, wenn verschiedene Aufgaben an verschiedene spezialisierte Agenten weitergeleitet werden sollen. Ein zentraler Triage-Agent empfängt die Eingabe, klassifiziert sie und leitet sie an den richtigen spezialisierten Agenten weiter.</p><p>Für Selbständige ist das Routing-Muster besonders in der Kundenkommunikation nützlich. Ein eingehender Triage-Agent prüft jede E-Mail und entscheidet: Ist das eine Anfrage nach einem Angebot, die an den Angebots-Agenten weitergeleitet wird? Eine Terminanfrage für den Kalender-Agenten? Eine technische Frage für den Recherche-Agenten? Oder eine Beschwerde, die zur menschlichen Prüfung markiert wird?</p><p>Das Routing-Muster macht Systeme effizienter, weil jeder Agent in seinem Bereich mit optimiertem Kontext und optimierten Werkzeugen arbeitet, anstatt ein Generalist-Agent alles gleich gut zu behandeln.</p><h2 id="die-kritische-grenze-wann-multi-agenten-zu-viel-werden" tabindex="-1">Die kritische Grenze: Wann Multi-Agenten zu viel werden <a class="header-anchor" href="#die-kritische-grenze-wann-multi-agenten-zu-viel-werden" aria-label="Permalink to &quot;Die kritische Grenze: Wann Multi-Agenten zu viel werden&quot;">​</a></h2><p>Multi-Agenten-Systeme haben eine Schattenseite, die in der Begeisterung über die Möglichkeiten leicht übersehen wird: Sie sind schwerer zu debuggen, schwerer zu kontrollieren und teurer zu betreiben als einzelne Agenten.</p><p>Wenn ein Fehler in einem Multi-Agenten-System auftritt, ist schwerer zu erkennen, welcher Agent das Problem verursacht hat. Jeder zusätzliche Agent ist ein zusätzlicher Punkt, an dem Informationen falsch weitergegeben, falsch interpretiert oder falsch verarbeitet werden können. Und jeder Agent verbraucht Tokens und Zeit.</p><p>Die Empfehlung aus der Produktionspraxis 2026 lautet: Starten Sie mit höchstens zwei Agenten in einer Kette. Prüfen Sie das System gründlich. Fügen Sie einen dritten Agenten nur hinzu, wenn Sie verstanden haben, wie die ersten beiden miteinander interagieren. Dokumentieren Sie, was jeder Agent bekommt und was er zurückgibt.</p><p>Für Selbständige ohne technisches Hintergrundwissen ist die praktische Empfehlung noch konservativer: Beginnen Sie mit dem sequenziellen Muster, weil es am einfachsten zu verstehen und zu prüfen ist. Erweitern Sie zu Orchestrator-Worker oder Evaluator-Optimizer, wenn Sie die Grundmuster beherrschen und einen konkreten Bedarf erkennen.</p><h2 id="praktische-multi-agenten-workflows-fur-selbstandige" tabindex="-1">Praktische Multi-Agenten-Workflows für Selbständige <a class="header-anchor" href="#praktische-multi-agenten-workflows-fur-selbstandige" aria-label="Permalink to &quot;Praktische Multi-Agenten-Workflows für Selbständige&quot;">​</a></h2><p>Abschließend drei konkrete Multi-Agenten-Workflows, die für Selbständige sofort umsetzbar sind.</p><p>Der erste ist die Marktanalyse in drei Stufen. Stufe 1 ist ein Recherche-Agent, der parallele Suchen zu Markt, Wettbewerbern und Zielgruppe durchführt und ein strukturiertes Briefing liefert. Stufe 2 ist ein Analyse-Agent, der das Briefing auswertet, Muster erkennt und Schlussfolgerungen zieht. Stufe 3 ist ein Format-Agent, der das Analyseergebnis in das gewünschte Ausgabeformat bringt, zum Beispiel eine Executive Summary, eine Tabellenübersicht und drei Handlungsempfehlungen.</p><p>Der zweite Workflow ist das Buchkapitel-Redaktionssystem. Ein Recherche-Agent liefert das Briefing. Ein Schreib-Agent erstellt den Entwurf. Ein Evaluator-Agent prüft den Entwurf nach Stilprofil, Faktenbelegen und Struktur und liefert Feedback. Der Schreib-Agent überarbeitet. Sie prüfen das Ergebnis und geben frei.</p><p>Der dritte Workflow ist die Angebotsqualitätssicherung. Ein Struktur-Agent erstellt den Angebotsrahmen aus Ihren Notizen. Ein Vollständigkeits-Agent prüft, ob alle notwendigen Angaben enthalten sind: Leistungsumfang, Abgrenzungen, Annahmen, Zeitrahmen, offene Fragen. Ein Ton-Agent prüft, ob die Sprache zur Kundenbeziehung passt. Sie bekommen das dreifach geprüfte Angebot zur finalen Überarbeitung und Freigabe.</p>',45)),l(n)])}const p=r(u,[["render",d]]);export{m as __pageData,p as default};
